<?php
require __DIR__.'/inc/bootstrap.php';$u=require_login(['admin','superadmin']);$cid=(int)($_GET['id']??0);$scope=($_GET['scope']??'overall')==='overall'?'overall':(valid_month($_GET['scope']??'')??date('Y-m'));
$creator=q("SELECT id,name FROM users WHERE id=? AND role='creator'",[$cid])->fetch();if(!$creator){http_response_code(404);exit('Creator not found');}
$plan=creator_plan($cid);$board=creator_board($cid,$scope);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();try{
 if((int)($_POST['revision']??-1)!==$board['revision'])throw new InvalidArgumentException('This board changed. Refresh before saving.');
 $goals=[];$known=array_column($scope==='overall'?$board['goals']:monthly_goal_definitions($cid,$scope),null,'key');
 foreach($_POST['goals']??[] as $row){if(count($goals)>=30)throw new InvalidArgumentException('Use up to 30 goals.');$title=trim((string)($row['title']??''));if($title==='')continue;if(mb_strlen($title)>120)throw new InvalidArgumentException('Goal names must be at most 120 characters.');$type=$row['type']??'number';if(!isset(PLAN_TYPES[$type]))throw new InvalidArgumentException('Invalid goal type');$key=(string)($row['key']??'');$old=$known[$key]??null;if(!$old)$key='board_'.bin2hex(random_bytes(10));if($old&&($old['source']??'manual')!=='manual'&&$old['type']!==$type)throw new InvalidArgumentException('Keep the value type for linked monthly goals.');$goals[]=['key'=>$key,'title'=>$title,'type'=>$type,'target'=>typed_value($type,$row['target']??''),'source'=>$scope==='overall'?'manual':($old['source']??'manual'),'current'=>$scope==='overall'?typed_value($type,$row['current']??''):null];}
 $keys=[];foreach($plan['phases'] as $phase)foreach($phase['miles'] as $task)$keys[]=$task['key'];
 $next=['vision'=>mb_substr(trim((string)($_POST['vision']??'')),0,3000),'goals'=>$goals,'tasks'=>array_values(array_intersect($keys,(array)($_POST['tasks']??[]))),'configured'=>true];
 save_creator_board($cid,$scope,$next,$board['revision']);log_activity($cid,(int)$u['id'],'plan',null,'Updated '.$scope.' board');flash('Board saved.');redirect('creator.php?id='.$cid.($scope==='overall'?'':'&view=monthly&m='.$scope));
 }catch(InvalidArgumentException $e){$error=$e->getMessage();}
}
if($scope!=='overall'&&empty($board['configured'])){$board['goals']=$plan['goals'];foreach($plan['phases'] as $phase)foreach($phase['miles'] as $task)$board['tasks'][]=$task['key'];}
function board_goal_row(array $g,int|string $i,bool $overall):void{?><div class="board-goal-row"><input type="hidden" name="goals[<?= $i ?>][key]" value="<?= e($g['key']??'') ?>"><label>Goal<input name="goals[<?= $i ?>][title]" value="<?= e($g['title']??'') ?>" maxlength="120"></label><label>Type<select name="goals[<?= $i ?>][type]"><?php foreach(PLAN_TYPES as $k=>$v):?><option value="<?= $k ?>" <?= ($g['type']??'number')===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach;?></select></label><label>Target<input name="goals[<?= $i ?>][target]" value="<?= e($g['target']??'') ?>"></label><?php if($overall):?><label>Current result<input name="goals[<?= $i ?>][current]" value="<?= e($g['current']??'') ?>" placeholder="Checkbox: 1 or 0"></label><?php endif;?><button class="btn sm danger" type="button" data-remove-goal>Remove</button></div><?php }
page_header('Edit board');?><a class="back" href="creator.php?id=<?= $cid ?>">Back to creator</a><h1><?= e($creator['name']) ?> · <?= $scope==='overall'?'Overall vision':e(month_label($scope)).' focus' ?></h1>
<?php if($error):?><div class="flash err"><?= e($error) ?></div><?php endif;?>
<form method="post" class="panel form"><?= csrf_field() ?><input type="hidden" name="revision" value="<?= $board['revision'] ?>"><label><?= $scope==='overall'?'Overall vision':'This month’s focus' ?><textarea name="vision" maxlength="3000" rows="3"><?= e($board['vision']) ?></textarea></label><p class="hint"><?= $scope==='overall'?'These goals and results are independent of all monthly targets.':'These targets and selected steps apply only to this month. Existing results are preserved.' ?></p><div id="board-goals"><?php foreach($board['goals'] as $i=>$g)board_goal_row($g,$i,$scope==='overall');?></div><button class="btn sm" type="button" id="board-add">Add goal</button>
<?php if($scope!=='overall'):?><h2>Work planned this month</h2><?php foreach($plan['phases'] as $phase):?><h3><?= e($phase['name']) ?></h3><?php foreach($phase['miles'] as $task):?><label class="check"><input type="checkbox" name="tasks[]" value="<?= e($task['key']) ?>" <?= in_array($task['key'],$board['tasks'],true)?'checked':'' ?>><?= e($task['t']) ?></label><?php endforeach;endforeach;endif;?>
<div class="plan-actions"><button class="btn primary">Save board</button></div></form><template id="board-template"><?php board_goal_row([],'__INDEX__',$scope==='overall');?></template>
<?php page_footer(['board.js']); ?>
